function isGood(nums) {
  const n = nums.length - 1;
  const count = new Array(n + 1).fill(0);
  for (const num of nums) {
    if (num > n) {
      return false;
    }
    count[num]++;
  }
  for (let value = 1; value < n; value++) {
    if (count[value] !== 1) {
      return false;
    }
  }
  return count[n] === 2;
}

