function generate(rand, size) {
  const maxLength = size === 'large' ? 100 : 8;
  const length = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * maxLength);
  const pick = rand();
  if (pick < 0.2) {
    const top = size === 'large' ? 200 : 6;
    return [Array.from({ length }, () => 1 + Math.floor(rand() * top))];
  }
  const n = Math.max(1, length - 1);
  const nums = [];
  for (let v = 1; v <= n; v++) nums.push(v);
  nums.push(n);
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  const change = rand();
  if (change < 0.2) nums[Math.floor(rand() * nums.length)] = 1 + Math.floor(rand() * (n + 2));
  else if (change < 0.3 && nums.length > 1) nums.pop();
  else if (change < 0.4 && nums.length < maxLength) nums.push(1 + Math.floor(rand() * (n + 1)));
  return [nums];
}
